    ('binary-classification','Binary Classification','طبقه‌بندی دودویی','ml',['classification','precision','recall'],'طبقه‌بندی دودویی؛ پیش‌بینی بین دو حالت مثل اسپم/غیر اسپم یا بیمار/سالم. خروجی چنین مدلی معمولاً یکی از دو کلاس است؛ مثلاً تشخیص ایمیل اسپم یا غیر اسپم.'),
    ('bloom-filter','Bloom Filter','فیلتر بلوم','software',['data-pipeline','vector-database'],'فیلتر بلوم؛ ساختار داده‌ای برای بررسی سریع این‌که آیا یک آیتم احتمالاً در مجموعه هست یا نه. مزیت آن سرعت و مصرف حافظه کم است، اما ممکن است وجود یک آیتم را اشتباه مثبت اعلام کند و برای پاسخ قطعی مناسب نیست.'),
    ('bots','Bots','بات‌ها','application',['chatbot','agent'],'بات‌ها؛ برنامه‌های خودکار که کارهای تکراری مثل پاسخ به پیام‌ها را انجام می‌دهند. بات‌ها می‌توانند برای پاسخ‌گویی، جمع‌آوری اطلاعات، اجرای وظایف تکراری و ارتباط خودکار با کاربران استفاده شوند.'),
    ('bounding-box','Bounding Box','جعبه محدودکننده','application',['computer-vision','yolo','object-detection'],'جعبه محدودکننده؛ مستطیلی روی تصویر که محل یک شیء را نشان می‌دهد. در تشخیص اشیا، هر جعبه معمولاً همراه با برچسب شیء و میزان اطمینان مدل ارائه می‌شود.'),
    ('business-intelligence','Business Intelligence (BI)','هوش کسب‌وکار','software',['predictive-analytics','kpi','exploratory-data-analysis'],'هوش کسب‌وکار؛ تحلیل داده‌ها برای تصمیم‌گیری بهتر در سازمان. BI معمولاً داده‌های فروش، مالی، مشتری و عملیات را به گزارش و بینش قابل استفاده برای مدیران تبدیل می‌کند.'),
    ('calibration','Calibration','کالیبراسیون','evaluation',['precision','llm-evaluation','benchmark'],'کالیبراسیون؛ تنظیم خروجی‌های احتمالی مدل تا با واقعیت بیشتر هماهنگ باشند. مدل کالیبره‌شده وقتی مثلاً احتمال ۸۰ درصد اعلام می‌کند، در شرایط مشابه باید تقریباً در ۸۰ درصد موارد درست باشد.'),
    ('candidate-generation','Candidate Generation','تولید نامزد','application',['reranking','retrieval','embedding'],'تولید نامزد؛ مرحله اولیه در سیستم‌های پیشنهاددهنده برای انتخاب چند گزینه از بین همه. این مرحله فضای جست‌وجو را کوچک می‌کند تا مراحل بعدی سیستم پیشنهاددهنده بتوانند گزینه‌ها را دقیق‌تر رتبه‌بندی کنند.'),
    ('capacity','Capacity','ظرفیت مدل','dl',['parameter','overfitting','bias-variance-tradeoff'],'ظرفیت مدل؛ توانایی مدل برای یادگیری الگوهای پیچیده (مدل‌های بزرگ ظرفیت بیشتری دارند). ظرفیت بیشتر به مدل اجازه می‌دهد الگوهای پیچیده‌تری را یاد بگیرد، اما به‌تنهایی تضمین‌کننده عملکرد بهتر نیست.'),
    ('cascade-model','Cascade Model','مدل آبشاری','deployment',['model-routing','latency','deployment'],'مدل آبشاری؛ ترکیب چند مدل که هر کدام بخشی از تصمیم‌گیری را انجام می‌دهند. این معماری می‌تواند با استفاده از مدل‌های ساده‌تر در مراحل اولیه و مدل‌های دقیق‌تر در مراحل بعدی، هزینه پردازش را کاهش دهد.'),
    ('causality','Causality','علیت','math',['correlation','exploratory-data-analysis','statistic'],'علیت؛ بررسی روابط علت و معلول در داده‌ها، فراتر از همبستگی ساده. دانستن اینکه دو اتفاق با هم مرتبط‌اند با دانستن اینکه یکی علت دیگری است تفاوت دارد و تحلیل علی برای تشخیص این تفاوت به کار می‌رود.'),
    ('chain-of-thought','Chain-of-Thought','زنجیره فکر','prompt',['chain-of-thought-prompting','reasoning-model','prompt-engineering'],'زنجیره فکر؛ روشی برای هدایت مدل به سمت حل مرحله‌ای یک مسئله؛ جزئیات استدلال داخلی مدل لزوماً نباید نمایش داده شوند.'),
    ('chain-of-thought-prompting','Chain-of-Thought Prompting','پرامپت‌دهی زنجیره‌ای','prompt',['chain-of-thought','few-shot-prompting','prompt-engineering'],'پرامپت‌دهی زنجیره‌ای؛ روشی برای درخواست حل مرحله‌ای مسئله از مدل، به‌ویژه برای مسائل چندمرحله‌ای.'),
    ('chatbot','Chatbot','چت‌بات','application',['llm','ai-assistant','bots'],'چت‌بات؛ برنامه‌ای که مکالمه متنی یا صوتی با انسان را شبیه‌سازی می‌کند. چت‌بات‌ها می‌توانند برای پاسخ به پرسش‌های متداول، پشتیبانی مشتری، راهنمایی کاربران و انجام برخی فرآیندها استفاده شوند.'),
    ('chatgpt','ChatGPT','چت‌جی‌پی‌تی','llm',['llm','ai-assistant','language-model'],'چت‌جی‌پی‌تی؛ یک مدل زبانی بزرگ معروف که برای چت، پاسخ‌گویی و تولید متن استفاده می‌شود. کاربر می‌تواند با آن گفتگو کند، سؤال بپرسد، متن تولید یا خلاصه کند و در بسیاری از کارهای فکری از آن کمک بگیرد.'),
    ('chunk','Chunk','قطعه','rag',['chunking','context-window'],'قطعه؛ بخشی از یک سند که پس از Chunking به‌عنوان یک واحد مستقل برای پردازش یا بازیابی استفاده می‌شود.'),
    ('chunking','Chunking','قطعه‌بندی','rag',['chunk','embedding','retrieval'],'قطعه‌بندی؛ تقسیم یک سند یا متن بزرگ به بخش‌های کوچک‌تر تا جست‌وجو، پردازش و استفاده از آن برای مدل آسان‌تر شود.'),
    ('citation','Citation','ارجاع','rag',['grounding','retrieval','hallucination'],'ارجاع؛ اشاره به منبعی که اطلاعات استفاده‌شده برای تولید یک پاسخ از آن آمده است.'),
    ('class-imbalance','Class Imbalance','عدم توازن کلاس','ml',['classification','recall','evaluation-metric'],'عدم توازن کلاس؛ زمانی که تعداد نمونه‌های یک برچسب خیلی کمتر از بقیه است و مدل به سمت برچسب‌های پرتکرار متمایل می‌شود. در چنین شرایطی ممکن است مدل کلاس پرتعداد را خوب تشخیص دهد اما در شناسایی کلاس کم‌تعداد، که گاهی مهم‌تر است، ضعیف باشد.'),
    ('classification','Classification','طبقه‌بندی','ml',['binary-classification','decision-tree','label'],'طبقه‌بندی؛ پیش‌بینی این‌که ورودی به کدام دسته یا برچسب تعلق دارد. برای مثال می‌توان پیام‌ها را به اسپم و غیر اسپم یا درخواست‌های مشتری را به چند دسته موضوعی تقسیم کرد.'),
    ('cloud-ai','Cloud AI','هوش مصنوعی ابری','hardware',['edge-ai','inference','deployment'],'هوش مصنوعی ابری؛ اجرای مدل‌های هوش مصنوعی روی سرورهای ابری مثل AWS یا Azure به جای کامپیوتر شخصی. مزیت آن دسترسی به توان پردازشی و مدل‌های قدرتمند بدون نیاز به تهیه و نگهداری سخت‌افزار سنگین است.'),
    ('clustering','Clustering','خوشه‌بندی','ml',['k-means','unsupervised-learning'],'خوشه‌بندی؛ گروه‌بندی خودکار داده‌های مشابه بدون برچسب‌های از پیش تعریف‌شده. این روش برای کشف گروه‌های طبیعی در داده، مانند دسته‌بندی مشتریان بر اساس رفتار، کاربرد زیادی دارد.'),
    ('code-generation','Code Generation','تولید کد','application',['llm','hallucination','prompt-engineering'],'تولید کد؛ استفاده از مدل‌های زبانی برای نوشتن یا تکمیل کد برنامه‌نویسی. ابزارهای تولید کد می‌توانند نوشتن کد، تکمیل بخش‌های ناقص، توضیح کد و ایجاد تست را سریع‌تر کنند، اما خروجی آن‌ها باید بررسی شود.'),
    ('cognitive-computing','Cognitive Computing','محاسبات شناختی','fundamentals',['ai','nlp'],'محاسبات شناختی؛ سیستم‌هایی که تلاش می‌کنند رفتار و فکر انسان را شبیه‌سازی کنند. این اصطلاح بیشتر برای سیستم‌هایی به کار می‌رود که قصد دارند درک، استدلال یا تعامل شبیه انسان را در یک کاربرد مشخص فراهم کنند.'),
    ('computer-vision','Computer Vision','بینایی کامپیوتر','application',['bounding-box','vlm','yolo'],'بینایی کامپیوتر؛ شاخه‌ای از هوش مصنوعی که به درک و تحلیل تصاویر و ویدیوها می‌پردازد. کاربردهای آن شامل تشخیص چهره و اشیا، بررسی تصاویر پزشکی، کنترل کیفیت و تحلیل ویدیو است.'),
    ('concept-drift','Concept Drift','رانش مفهوم','deployment',['model-drift','continuous-learning','training-data'],'رانش مفهوم؛ تغییر تدریجی الگوهای داده در طول زمان که باعث افت عملکرد مدل می‌شود. اگر رفتار داده‌های واقعی تغییر کند، مدلی که قبلاً دقیق بوده ممکن است به مرور نیاز به پایش و بازآموزی داشته باشد.'),
    ('confusion-matrix','Confusion Matrix','ماتریس درهم‌ریختگی','evaluation',['precision','recall','false-positive','false-negative'],'ماتریس درهم‌ریختگی؛ جدول برای نمایش تعداد پیش‌بینی‌های درست و غلط برای هر کلاس. از این جدول می‌توان مواردی مانند مثبت کاذب و منفی کاذب را دید و فهمید مدل در کدام کلاس‌ها بیشتر خطا می‌کند.'),
    ('context','Context','زمینه','prompt',['context-window','prompt','context-engineering'],'زمینه؛ اطلاعاتی که همراه درخواست در اختیار مدل قرار می‌گیرد تا مدل بتواند پاسخ مرتبط‌تر و دقیق‌تری تولید کند.'),
    ('context-engineering','Context Engineering','مهندسی زمینه','prompt',['context','prompt-engineering','context-retrieval'],'مهندسی زمینه؛ طراحی و مدیریت اطلاعاتی که به مدل داده می‌شود تا در هر مرحله زمینه مناسب برای تولید پاسخ بهتر را داشته باشد.'),
    ('context-retrieval','Context Retrieval','بازیابی زمینه','rag',['retrieval','rag','context'],'بازیابی زمینه؛ پیدا کردن اطلاعاتی که باید به‌عنوان زمینه در اختیار مدل قرار گیرد تا پاسخ دقیق‌تر شود.'),
    ('context-window','Context Window','پنجره متن','llm',['token','long-context','context'],'پنجره متن؛ حداکثر مقداری از متن که یک مدل زبانی می‌تواند در یک درخواست پردازش کند. هرچه پنجره متن بزرگ‌تر باشد، مدل می‌تواند اطلاعات بیشتری از یک مکالمه یا سند را هم‌زمان در نظر بگیرد.'),
    ('continuous-learning','Continuous Learning','یادگیری پیوسته','training',['concept-drift','federated-learning','post-training'],'یادگیری پیوسته؛ توانایی سیستم برای آپدیت شدن و یادگیری از داده‌های جدید در طول زمان. در این رویکرد مدل یا سیستم به شکل مداوم با داده‌های جدید به‌روزرسانی می‌شود؛ البته کیفیت داده جدید باید کنترل شود.'),
    ('convergence','Convergence','همگرایی','training',['optimization','learning-rate','cost-function'],'همگرایی؛ نقطه‌ای در آموزش که در آن خطا کم تغییر می‌کند و مدل به حالت پایدار رسیده است. همگرایی مناسب معمولاً نشان می‌دهد فرآیند بهینه‌سازی به ناحیه‌ای رسیده که تغییرات آن کوچک شده‌اند.'),
    ('core-model','Core Model','مدل هسته','llm',['foundation-model','pretrained-model','model'],'مدل هسته؛ مدل اصلی هوش مصنوعی که قابلیت‌های دیگر روی آن سوار می‌شوند. مدل‌های دیگر یا قابلیت‌های محصول می‌توانند بر پایه این مدل اصلی ساخته یا تنظیم شوند.'),
    ('cost-function','Cost Function','تابع هزینه','math',['loss-function','optimization','optimizer'],'تابع هزینه؛ فرمولی برای محاسبه خطای مدل که هدف آموزش کاهش آن است. در زمان آموزش، الگوریتم تلاش می‌کند پارامترهای مدل را طوری تغییر دهد که مقدار این تابع کمتر شود.'),
    ('cpu','CPU (Central Processing Unit)','واحد پردازش مرکزی','hardware',['gpu','tpu'],'واحد پردازش مرکزی؛ بخش اصلی کامپیوتر برای اجرای دستورها، که در آموزش مدل هم استفاده می‌شود. CPU برای اجرای عمومی برنامه‌ها مناسب است و در برخی مراحل آماده‌سازی داده و اجرای مدل نیز استفاده می‌شود.'),
    ('cross-entropy-loss','Cross-Entropy Loss','زیان آنتروپی متقابل','math',['loss-function','classification','cost-function'],'زیان آنتروپی متقابل؛ تابع خطای متداول برای مسائل طبقه‌بندی. هرچه احتمال اختصاص‌داده‌شده به پاسخ درست کمتر باشد، این تابع معمولاً خطای بیشتری ایجاد می‌کند.'),
    ('cross-validation','Cross-Validation','اعتبارسنجی متقابل','evaluation',['validation-data','training-data','overfitting'],'اعتبارسنجی متقابل؛ روش تقسیم داده‌ها به چند بخش برای ارزیابی پایدارتر عملکرد مدل. این روش کمک می‌کند ارزیابی مدل فقط به یک تقسیم تصادفی خاص از داده‌ها وابسته نباشد.'),
    ('data-augmentation','Data Augmentation','تقویت داده','training',['training-data','synthetic-data','overfitting'],'تقویت داده؛ ایجاد نسخه‌های کمی تغییرکرده از داده‌های موجود برای افزایش حجم داده آموزشی. برای تصویر می‌توان کارهایی مثل چرخش یا تغییر جزئی انجام داد و برای برخی داده‌های دیگر نیز روش‌های مناسب افزایش داده وجود دارد.'),
    ('data-cleaning','Data Cleaning','تمیز کردن داده','ml',['dataset','exploratory-data-analysis','data-pipeline'],'تمیز کردن داده؛ حذف خطاها، مقادیر ناقص و تناقض‌ها از مجموعه‌داده. داده تمیزتر معمولاً باعث می‌شود تحلیل‌ها و مدل‌های یادگیری ماشین قابل اعتمادتر شوند.'),
    ('data-governance','Data Governance','حاکمیت داده','ethics',['data-privacy','ai-governance','data-labeling'],'حاکمیت داده؛ قوانین و فرآیندها برای مدیریت مسئولانه داده‌ها در سازمان. حاکمیت داده درباره مالکیت، کیفیت، دسترسی، امنیت و نحوه استفاده از داده‌ها تصمیم‌گیری می‌کند.'),
    ('data-labeling','Data Labeling','برچسب‌گذاری داده','training',['label','ground-truth','supervised-learning'],'برچسب‌گذاری داده؛ اضافه کردن پاسخ صحیح (برچسب) به نمونه‌ها برای آموزش مدل. برچسب‌های باکیفیت اهمیت زیادی دارند، چون مدل در بسیاری از روش‌های نظارت‌شده مستقیماً از همین پاسخ‌های صحیح یاد می‌گیرد.'),
    ('data-mining','Data Mining','کاوش داده','ml',['big-data','clustering','exploratory-data-analysis'],'کاوش داده؛ کشف الگوها و روابط مفید در مجموعه‌داده‌های بزرگ. هدف آن پیدا کردن اطلاعاتی است که در حجم زیاد داده به‌سادگی با مشاهده دستی قابل تشخیص نیستند.'),
    ('data-pipeline','Data Pipeline','خط لوله داده','software',['etl','dataset','training-data'],'خط لوله داده؛ زنجیره مراحل جمع‌آوری، پردازش و انتقال داده تا مدل. پایپ‌لاین می‌تواند از دریافت داده شروع شود و تا پاک‌سازی، تبدیل، ذخیره‌سازی و آماده‌سازی آن برای مدل ادامه پیدا کند.'),
    ('data-privacy','Data Privacy','حریم خصوصی داده','security',['data-governance','federated-learning','ai-ethics'],'حریم خصوصی داده؛ محافظت از اطلاعات شخصی هنگام استفاده از آن‌ها در سیستم‌های هوش مصنوعی. در پروژه‌های AI باید مشخص باشد چه داده‌ای جمع‌آوری می‌شود، چه کسی به آن دسترسی دارد و برای چه منظوری استفاده می‌شود.'),
    ('data-science','Data Science','علم داده','fundamentals',['machine-learning','exploratory-data-analysis','statistic'],'علم داده؛ حوزه‌ای که با تحلیل داده، آمار و مدل‌سازی برای استخراج بینش سروکار دارد. علم داده ترکیبی از آمار، برنامه‌نویسی، تحلیل و دانش حوزه کسب‌وکار برای حل مسئله با داده است.'),
    ('dataset','Dataset','مجموعه‌داده','fundamentals',['training-data','validation-data','data-cleaning'],'مجموعه‌داده؛ مجموعه‌ای از نمونه‌ها که برای آموزش، اعتبارسنجی یا تست مدل استفاده می‌شود. کیفیت، اندازه و تنوع دیتاست مستقیماً روی توانایی مدل برای یادگیری و تعمیم اثر می‌گذارد.'),
    ('decision-boundary','Decision Boundary','مرز تصمیم','ml',['classification','bayes-classifier'],'مرز تصمیم؛ خط یا سطحی که مدل برای جدا کردن کلاس‌های مختلف رسم می‌کند. نقاط دو طرف این مرز از دید مدل به کلاس‌های متفاوتی تعلق دارند.'),
    ('decision-tree','Decision Tree','درخت تصمیم','ml',['classification','explainability','ensemble-learning'],'درخت تصمیم؛ مدل ساده‌ای که تصمیم‌ها را به صورت شاخه‌های درختی از پرسش‌ها نمایش می‌دهد. مزیت مهم درخت تصمیم این است که منطق تصمیم‌گیری آن در بسیاری از مسائل نسبتاً قابل فهم و قابل توضیح است.'),
    ('deep-learning','Deep Learning','یادگیری عمیق','dl',['neural-network','machine-learning','transformer'],'یادگیری عمیق؛ زیرشاخه‌ای از یادگیری ماشین که از شبکه‌های عصبی چندلایه استفاده می‌کند. این روش در حوزه‌هایی مانند تصویر، صدا و زبان طبیعی به‌ویژه زمانی که داده زیادی وجود دارد، بسیار قدرتمند است.'),
    ('deepfake','Deepfake','دیپ‌فیک','ethics',['synthetic-media','generative-model','ai-ethics'],'دیپ‌فیک؛ تصویر یا ویدیوی ساختگی بسیار واقعی که توسط هوش مصنوعی تولید یا دستکاری شده است. از این فناوری می‌توان برای تولید محتوای خلاقانه استفاده کرد، اما امکان سوءاستفاده و جعل هویت نیز وجود دارد.'),
    ('density-estimation','Density Estimation','برآورد چگالی','math',['bayesian-inference','anomaly-detection','autoencoder'],'برآورد چگالی؛ تخمین شکل توزیع احتمالاتی داده‌ها. از آن می‌توان برای درک شکل توزیع داده، شناسایی نقاط غیرعادی یا مدل‌سازی احتمالات استفاده کرد.'),
    ('deployment','Deployment','استقرار','deployment',['mlops','latency','model-drift'],'استقرار؛ مرحله‌ای که در آن مدل آموزش‌دیده در محصول یا سرویس واقعی استفاده می‌شود. بعد از استقرار، مدل باید از نظر کیفیت، سرعت، هزینه و تغییر رفتار داده‌ها نیز پایش شود.'),
    ('diffusion','Diffusion','انتشار','generative',['diffusion-model','stable-diffusion','text-to-image'],'انتشار؛ خانواده‌ای از روش‌های مولد که با یادگیری تبدیل داده به نویز و برعکس، می‌توانند محتوای جدید تولید کنند.'),
    ('diffusion-model','Diffusion Model','مدل انتشار','generative',['diffusion','stable-diffusion','text-to-image'],'مدل انتشار؛ مدل مولدی که با معکوس کردن فرآیند نویزی شدن، تصویر یا داده جدید تولید می‌کند. مدل‌های انتشار امروزی به‌ویژه در تولید و ویرایش تصویر و برخی انواع رسانه عملکرد قدرتمندی دارند.'),
    ('dimensionality-reduction','Dimensionality Reduction','کاهش بُعد','ml',['feature-engineering','autoencoder','embedding'],'کاهش بُعد؛ کاهش تعداد ویژگی‌ها برای ساده‌تر شدن مدل در عین حفظ اطلاعات مهم. کاهش بُعد می‌تواند داده را برای تحلیل یا نمایش ساده‌تر کند و گاهی زمان و هزینه پردازش را نیز کاهش دهد.'),
    ('discriminative-model','Discriminative Model','مدل تمایزبخش','ml',['generative-model','classification'],'مدل تمایزبخش؛ مدلی که بیشتر برای تشخیص، طبقه‌بندی یا پیش‌بینی تفاوت بین گروه‌ها استفاده می‌شود، نه تولید محتوای جدید.'),
    ('distillation','Distillation / Knowledge Distillation','تقطیر دانش','training',['slm','quantization','llm'],'تقطیر دانش؛ روشی برای آموزش یک مدل کوچک‌تر با استفاده از دانش یا خروجی‌های یک مدل بزرگ‌تر تا با هزینه کمتر عملکرد مناسبی داشته باشد.'),
    ('distributed-training','Distributed Training','آموزش توزیع‌شده','training',['gpu','batch-size','job-scheduling'],'آموزش توزیع‌شده؛ آموزش مدل روی چندین دستگاه یا سرور برای سرعت بیشتر. با تقسیم فرآیند آموزش بین چند پردازنده یا ماشین می‌توان آموزش مدل‌های بزرگ را سریع‌تر یا امکان‌پذیرتر کرد.'),
    ('domain-adaptation','Domain Adaptation','سازگاری دامنه','training',['transfer-learning','fine-tuning','concept-drift'],'سازگاری دامنه؛ تنظیم مدل برای عملکرد بهتر روی نوع جدیدی از داده‌ها. این روش زمانی مهم است که داده‌ای که مدل در محیط واقعی می‌بیند با داده آموزشی اولیه تفاوت داشته باشد.'),
    ('domain-knowledge','Domain Knowledge','دانش دامنه','fundamentals',['feature-engineering','rag'],'دانش دامنه؛ دانش تخصصی در یک حوزه خاص که برای طراحی بهتر مدل‌ها استفاده می‌شود. اضافه کردن دانش حوزه‌ای درست می‌تواند پاسخ‌ها و تصمیم‌های سیستم را برای یک صنعت یا سازمان مرتبط‌تر کند.'),
    ('dpo','DPO (Direct Preference Optimization)','بهینه‌سازی مستقیم ترجیحات','alignment',['rlhf','reward-model','alignment'],'بهینه‌سازی مستقیم ترجیحات؛ روشی برای تنظیم مدل بر اساس ترجیح انسان بین پاسخ‌های مختلف، بدون نیاز به ساخت یک مدل پاداش جداگانه.'),
    ('edge-ai','Edge AI','هوش مصنوعی لبه','hardware',['cloud-ai','slm','quantized-model'],'هوش مصنوعی لبه؛ اجرای مدل‌های هوش مصنوعی روی دستگاه‌های محلی مثل موبایل، نه در سرورهای ابری. این رویکرد برای کاربردهایی که سرعت پاسخ، قطع نبودن اینترنت یا حفظ حریم خصوصی مهم است، مفید است.'),
    ('embedding','Embedding','جای‌گذاری','ml',['vector-database','semantic-search','word-embedding'],'جای‌گذاری؛ نمایش کلمات، تصاویر یا داده‌ها به صورت بردارهای عددی که معنای آن‌ها را حفظ می‌کند. Embeddingها برای مقایسه شباهت معنایی، جست‌وجوی مفهومی، سیستم‌های پیشنهاددهنده و RAG کاربرد زیادی دارند.'),
    ('ensemble-learning','Ensemble Learning','یادگیری گروهی','ml',['decision-tree','cascade-model','overfitting'],'یادگیری گروهی؛ ترکیب چند مدل برای رسیدن به عملکرد بهتر از هر مدل به‌تنهایی. ترکیب مدل‌های متفاوت می‌تواند خطاهای آن‌ها را تا حدی جبران کند و نتیجه نهایی را بهتر کند.'),
    ('epoch','Epoch','دوره','training',['batch-size','convergence','batch-size'],'دوره؛ یک عبور کامل مدل از روی تمام داده‌های آموزشی. تعداد Epoch یکی از عوامل مؤثر بر میزان آموزش است و زیاد بودن آن همیشه به معنی عملکرد بهتر نیست.'),
    ('etl','ETL (Extract, Transform, Load)','استخراج، تبدیل، بارگذاری','software',['data-pipeline','data-cleaning','dataset'],'استخراج، تبدیل، بارگذاری؛ فرآیند جمع‌آوری، تمیز کردن و ذخیره‌سازی داده‌ها. ETL یکی از مراحل رایج آماده‌سازی داده برای انبار داده، گزارش‌گیری و تحلیل است.'),
    ('evaluation-metric','Evaluation Metric','معیار ارزیابی','evaluation',['precision','recall','benchmark'],'معیار ارزیابی؛ عددی برای سنجش کیفیت عملکرد مدل مثل دقت یا فراخوانی. انتخاب معیار درست به نوع مسئله بستگی دارد؛ مثلاً Accuracy برای همه مسائل انتخاب مناسبی نیست.'),
    ('explainability','Explainability','قابلیت توضیح','evaluation',['xai','decision-tree','ai-governance'],'قابلیت توضیح؛ میزان قابل فهم بودن تصمیم‌ها و خروجی‌های یک مدل برای انسان. توضیح‌پذیری در کاربردهای حساس کمک می‌کند انسان بفهمد چرا سیستم به یک نتیجه مشخص رسیده است.'),
    ('exploratory-data-analysis','Exploratory Data Analysis (EDA)','تحلیل اکتشافی داده','ml',['data-cleaning','data-science','statistic'],'تحلیل اکتشافی داده؛ بررسی اولیه داده‌ها با نمودارها و آمار ساده برای شناخت الگوها. EDA معمولاً قبل از مدل‌سازی انجام می‌شود تا خطاهای داده، الگوهای مهم و روابط احتمالی شناسایی شوند.'),
    ('false-negative','False Negative','منفی کاذب','evaluation',['confusion-matrix','recall','evaluation-metric'],'منفی کاذب؛ زمانی که مدل به‌اشتباه یک مورد مثبت را منفی تشخیص می‌دهد. مثلاً اگر یک تراکنش واقعاً تقلبی باشد اما سیستم آن را سالم اعلام کند، این یک False Negative است.'),
    ('false-positive','False Positive','مثبت کاذب','evaluation',['confusion-matrix','precision','evaluation-metric'],'مثبت کاذب؛ زمانی که مدل به‌اشتباه یک مورد منفی را مثبت تشخیص می‌دهد. مثلاً اگر سیستم یک تراکنش سالم را تقلبی تشخیص دهد، با یک False Positive روبه‌رو هستیم.'),
    ('feature','Feature','ویژگی','ml',['feature-engineering','dataset'],'ویژگی؛ یک خاصیت یا ستون از داده که مدل از آن برای یادگیری استفاده می‌کند. مثلاً سن مشتری، مبلغ خرید یا تعداد ورودهای کاربر می‌تواند یک Feature برای مدل باشد.'),
    ('feature-engineering','Feature Engineering','مهندسی ویژگی','ml',['feature','dimensionality-reduction','domain-knowledge'],'مهندسی ویژگی؛ ساخت یا انتخاب ویژگی‌های بهتر برای بهبود عملکرد مدل. ویژگی‌های مناسب می‌توانند اطلاعات مفیدتری در اختیار مدل قرار دهند و در برخی مسائل حتی از انتخاب مدل مهم‌تر باشند.'),
    ('federated-learning','Federated Learning','یادگیری فدره','training',['data-privacy','distributed-training'],'یادگیری فدره؛ آموزش مدل روی چند دستگاه بدون جمع کردن همه داده‌ها در یک جا، برای حفظ حریم خصوصی. داده خام روی دستگاه‌ها باقی می‌ماند و معمولاً فقط اطلاعات لازم برای به‌روزرسانی مدل بین آن‌ها ردوبدل می‌شود.'),
    ('few-shot-learning','Few-Shot Learning','یادگیری کم‌نمونه','training',['few-shot-prompting','zero-shot-learning','transfer-learning'],'یادگیری کم‌نمونه؛ توانایی مدل برای یادگیری از تعداد کمی مثال. در این روش چند نمونه در اختیار مدل قرار می‌گیرد تا بدون آموزش کامل دوباره، الگوی موردنظر را بهتر درک کند.'),
    ('few-shot-prompting','Few-shot Prompting','پرامپت‌دهی چندنمونه‌ای','prompt',['few-shot-learning','prompt','zero-shot-prompting'],'پرامپت‌دهی چندنمونه‌ای؛ قرار دادن چند مثال در Prompt برای نشان دادن الگوی پاسخ مورد انتظار به مدل.'),
    ('fine-tuning','Fine-tuning','تنظیم دقیق','training',['adapter','lora','sft'],'تنظیم دقیق؛ آموزش بیشتر یک مدل از پیش آموزش‌دیده روی داده‌های خاص. Fine-tuning زمانی مفید است که بخواهیم یک مدل عمومی را برای سبک، وظیفه یا حوزه مشخصی تخصصی‌تر کنیم.'),
    ('foundation-model','Foundation Model','مدل پایه','llm',['pretrained-model','llm','fine-tuning'],'مدل پایه؛ مدل بزرگی که روی داده‌های گسترده آموزش دیده و می‌توان از آن به‌عنوان پایه برای ساخت یا تخصصی‌سازی برنامه‌های مختلف هوش مصنوعی استفاده کرد.'),
    ('function-calling','Function Calling','فراخوانی تابع','agents',['tool-calling','tool-use','structured-output'],'فراخوانی تابع؛ روشی که مدل در آن مشخص می‌کند کدام تابع برنامه باید با چه ورودی‌هایی اجرا شود تا کاری خارج از توان مستقیم مدل انجام شود.'),
    ('gan','GAN (Generative Adversarial Network)','شبکه خصمانه مولد','generative',['generative-model','generative-ai','deep-learning'],'شبکه خصمانه مولد؛ شامل دو شبکه (تولیدکننده و تشخیص‌دهنده) که با هم رقابت می‌کنند تا داده واقعی‌نما تولید شود. رقابت بین دو شبکه باعث می‌شود تولیدکننده تلاش کند خروجی‌هایی شبیه داده واقعی بسازد و تشخیص‌دهنده آن‌ها را بهتر شناسایی کند.'),
    ('generative-ai','GenAI (Generative AI)','هوش مصنوعی مولد','generative',['generative-model','diffusion-model','llm'],'هوش مصنوعی مولد؛ نوعی هوش مصنوعی که محتوای جدید مثل متن، تصویر، صدا یا کد تولید می‌کند. مدل‌های مولد می‌توانند از یک دستور کاربر برای تولید متن، تصویر، صدا، ویدیو یا کد استفاده کنند.'),
    ('generative-model','Generative Model','مدل مولد','generative',['generative-ai','discriminative-model','diffusion-model'],'مدل مولد؛ مدلی که به‌جای فقط تشخیص یا دسته‌بندی داده‌ها، می‌تواند محتوای جدید مانند متن، تصویر، صدا، ویدیو یا کد تولید کند.'),
    ('gpu','GPU (Graphics Processing Unit)','واحد پردازش گرافیکی','hardware',['cpu','tpu','distributed-training'],'واحد پردازش گرافیکی؛ پردازنده‌ای بسیار موازی که برای آموزش مدل‌های عمیق بسیار سریع است. توان پردازش موازی GPU آن را برای عملیات بسیار زیاد و مشابه که در شبکه‌های عصبی رایج‌اند مناسب می‌کند.'),
    ('gnn','Graph Neural Network (GNN)','شبکه عصبی گراف','dl',['node','neural-network'],'شبکه عصبی گراف؛ مدلی برای داده‌هایی که ساختار شبکه‌ای یا گراف دارند. GNN برای مسائلی مانند شبکه‌های اجتماعی، ارتباط بین کالاها، مولکول‌ها و سیستم‌های دارای رابطه مناسب است.'),
    ('ground-truth','Ground Truth','حقیقت مرجع','evaluation',['data-labeling','evaluation-metric','supervised-learning'],'حقیقت مرجع؛ پاسخ واقعی و صحیح که مدل باید آن را یاد بگیرد. Ground Truth مبنای مقایسه مدل است و برای آموزش، ارزیابی و اندازه‌گیری خطای بسیاری از مدل‌ها اهمیت دارد.'),
    ('grounding','Grounding','اتکا به منبع','rag',['rag','citation','hallucination'],'اتکا به منبع؛ متصل کردن پاسخ مدل به داده یا منابع مشخص و قابل بررسی برای کاهش پاسخ‌های بی‌پایه.'),
    ('guardrails','Guardrails','گاردریل‌ها','ethics',['ai-safety','prompt-injection','jailbreak'],'گاردریل‌ها؛ قوانین، محدودیت‌ها و کنترل‌هایی که برای جلوگیری از خروجی‌ها یا رفتارهای نامناسب و ناامن در سیستم AI استفاده می‌شوند.'),
    ('hallucination','Hallucination','توهم','llm',['grounding','rag','llm-evaluation'],'توهم؛ زمانی که مدل هوش مصنوعی اطلاعات نادرست یا ساختگی را با اعتمادبه‌نفس تولید می‌کند. در کاربردهای حساس باید خروجی مدل با منابع معتبر بررسی شود، زیرا لحن مطمئن مدل به معنی درست بودن اطلاعات نیست.'),
    ('heuristic','Heuristic','روش سرانگشتی','fundamentals',['algorithm','optimization'],'روش سرانگشتی؛ قاعده‌های ساده و تقریبی برای حل سریع مسائل. روش‌های سرانگشتی معمولاً پاسخ تقریبی و سریع می‌دهند و لزوماً بهترین جواب ریاضی ممکن را پیدا نمی‌کنند.'),
    ('hidden-layer','Hidden Layer','لایه مخفی','dl',['layer','neural-network','deep-learning'],'لایه مخفی؛ لایه‌های میانی شبکه عصبی که بین ورودی و خروجی قرار دارند. تعداد و ساختار این لایه‌ها بخشی از معماری شبکه را تشکیل می‌دهد و بر توانایی یادگیری مدل اثر دارد.'),
    ('hybrid-search','Hybrid Search','جست‌وجوی ترکیبی','rag',['semantic-search','vector-search','retrieval'],'جست‌وجوی ترکیبی؛ ترکیب جست‌وجوی کلمه‌ای و معنایی برای پیدا کردن نتایج مرتبط‌تر.'),
    ('hyperparameter','Hyperparameter','فراپارامتر','training',['parameter','hyperparameter-tuning'],'فراپارامتر؛ تنظیماتی مثل نرخ یادگیری یا تعداد لایه‌ها که قبل از آموزش تعیین می‌شوند. این تنظیمات از پارامترهای داخلی مدل متفاوت‌اند، چون معمولاً توسط طراح یا فرآیند تنظیم مدل تعیین می‌شوند.'),
    ('hyperparameter-tuning','Hyperparameter Tuning','تنظیم فراپارامتر','training',['hyperparameter','bayesian-optimization','automl'],'تنظیم فراپارامتر؛ جست‌وجو برای پیدا کردن بهترین تنظیمات مدل. روش‌هایی مانند جست‌وجوی شبکه‌ای، جست‌وجوی تصادفی و بهینه‌سازی بیزی برای این کار استفاده می‌شوند.'),
    ('icl','ICL (In-Context Learning)','یادگیری در متن','prompt',['few-shot-prompting','context-window','prompt'],'یادگیری در متن؛ توانایی مدل‌های زبانی برای یادگیری از مثال‌هایی که همین‌الان در ورودی داده شده‌اند. مدل با دیدن نمونه‌های موجود در همان درخواست، بدون تغییر دائمی وزن‌هایش، نحوه پاسخ‌گویی را با مثال‌ها هماهنگ می‌کند.'),
    ('inference','Inference','استنتاج','deployment',['inference-api','latency','model'],'استنتاج؛ استفاده از مدل آموزش‌دیده برای پیش‌بینی یا تولید خروجی روی داده‌های جدید. هر بار که یک مدل آموزش‌دیده برای پاسخ به درخواست کاربر اجرا می‌شود، در حال انجام Inference است.'),
    ('inference-api','Inference API','API استنتاج','deployment',['inference','api','model-api'],'API استنتاج؛ سرویسی که یک ورودی را به مدل می‌دهد و خروجی تولیدشده توسط مدل را به برنامه برمی‌گرداند.'),
    ('inference-time-compute','Inference-Time Compute','محاسبات زمان استنتاج','llm',['inference','reasoning-model'],'محاسبات زمان استنتاج؛ منابع محاسباتی که مدل هنگام تولید پاسخ مصرف می‌کند و می‌توان با افزایش آن در برخی مدل‌ها کیفیت حل مسئله را بهبود داد.'),
    ('instruction-tuning','Instruction Tuning','تنظیم بر اساس دستور','training',['sft','rlhf','fine-tuning'],'تنظیم بر اساس دستور؛ آموزش مدل با نمونه‌هایی از دستور و پاسخ برای اینکه بهتر دستورهای انسانی را دنبال کند.'),
    ('iot','IoT (Internet of Things)','اینترنت اشیاء','hardware',['edge-ai','data-pipeline'],'اینترنت اشیاء؛ شبکه‌ای از دستگاه‌های فیزیکی متصل به اینترنت که داده تولید و ردوبدل می‌کنند. نمونه‌های آن شامل حسگرهای صنعتی، ساعت‌های هوشمند، تجهیزات خانه هوشمند و دستگاه‌های متصل هستند.'),
    ('jaccard-similarity','Jaccard Similarity','شباهت ژاکارد','math',['vector-search','semantic-search','embedding'],'شباهت ژاکارد؛ معیاری برای سنجش شباهت بین دو مجموعه. این معیار از نسبت اشتراک دو مجموعه به اجتماع آن‌ها به دست می‌آید و مقدار بیشتر نشان‌دهنده شباهت بیشتر است.'),
    ('jacobian','Jacobian','ژاکوبین','math',['jacobian-matrix','optimization','backpropagation'],'ژاکوبین؛ ماتریسی از مشتقات جزئی که در بهینه‌سازی و شبکه‌های عصبی کاربرد دارد. در شبکه‌های عصبی، ژاکوبین می‌تواند رابطه تغییرات چند خروجی نسبت به چند ورودی را نشان دهد و در محاسبات گرادیانی و بهینه‌سازی کاربرد دارد.'),
    ('jacobian-matrix','Jacobian Matrix','ماتریس ژاکوبین','math',['jacobian','backpropagation','optimizer'],'ماتریس ژاکوبین؛ ماتریسی از مشتقات جزئی که در پس‌انتشار و بهینه‌سازی استفاده می‌شود. این ماتریس در محاسبات مشتق چندمتغیره، تحلیل حساسیت و برخی روش‌های بهینه‌سازی شبکه‌های عصبی کاربرد دارد.'),
    ('jailbreak','Jailbreak','جیل‌بریک','security',['prompt-injection','guardrails','ai-safety'],'جیل‌بریک؛ تلاش برای دور زدن محدودیت‌ها و قواعد ایمنی یک مدل با استفاده از دستورها یا روش‌های خاص.'),
    ('jensen-shannon-divergence','Jensen-Shannon Divergence','واگرایی جنسن-شانون','math',['kl-divergence','density-estimation'],'واگرایی جنسن-شانون؛ معیاری برای سنجش تفاوت بین دو توزیع احتمالاتی. این معیار نسخه‌ای متقارن‌تر و معمولاً پایدارتر از مقایسه برخی توزیع‌های احتمالاتی است و مقدار آن برای توزیع‌های یکسان صفر می‌شود.'),
    ('jit-compilation','JIT Compilation','کامپایل لحظه‌ای','software',['inference','latency','optimization'],'کامپایل لحظه‌ای؛ تکنیکی برای بهینه‌سازی اجرای کد در زمان اجرا که در فریم‌ورک‌های یادگیری ماشین استفاده می‌شود. کد به جای اینکه همه‌اش از ابتدا کامپایل شود، در زمان اجرا و بر اساس نیاز بهینه و کامپایل می‌شود.'),
    ('job-scheduling','Job Scheduling','زمان‌بندی کار','hardware',['distributed-training','throughput'],'زمان‌بندی کار؛ مدیریت ترتیب اجرای وظایف در سیستم‌های توزیع‌شده آموزش مدل. زمان‌بندی مناسب کارها می‌تواند استفاده از GPU و سایر منابع محاسباتی را بهتر کند و زمان انتظار آموزش را کاهش دهد.'),
    ('joint-distribution','Joint Distribution','توزیع توأم','math',['joint-probability','bayesian-network'],'توزیع توأم؛ توزیع احتمالاتی چند متغیر با هم. این مفهوم برای بررسی رفتار چند متغیر به‌صورت هم‌زمان استفاده می‌شود و پایه برخی محاسبات احتمالاتی است.'),
    ('joint-probability','Joint Probability','احتمال توأم','math',['joint-distribution','bayes-theorem'],'احتمال توأم؛ احتمال رخ دادن هم‌زمان دو یا چند رویداد. برای مثال می‌توان احتمال هم‌زمان بارانی بودن هوا و لغو شدن یک رویداد را بررسی کرد.'),
    ('json-mode','JSON Mode','حالت JSON','llm',['structured-output','function-calling'],'حالت JSON؛ قابلیتی که مدل را برای تولید خروجی در قالب JSON هدایت می‌کند تا استفاده از پاسخ در نرم‌افزار آسان‌تر شود.'),
    ('jump-connection','Jump Connection','اتصال پرشی','dl',['neural-network','hidden-layer','convergence'],'اتصال پرشی؛ ارتباط مستقیم بین لایه‌های غیرمتوالی در شبکه‌های عصبی. اتصال پرشی اجازه می‌دهد اطلاعات یا گرادیان مسیر کوتاه‌تری بین لایه‌ها داشته باشد و در معماری‌های عمیق به بهبود آموزش کمک می‌کند.'),
    ('junction-tree-algorithm','Junction Tree Algorithm','الگوریتم درخت اتصال','math',['bayesian-network','bayesian-inference'],'الگوریتم درخت اتصال؛ روشی برای استنتاج در شبکه‌های بیزی. این الگوریتم شبکه احتمالاتی را به ساختاری تبدیل می‌کند که انجام برخی محاسبات استنتاجی در آن آسان‌تر شود.'),
    ('k-means','K-Means','کی‌مینز','ml',['clustering','unsupervised-learning'],'کی‌مینز؛ الگوریتم ساده و معروف برای خوشه‌بندی داده‌ها به چند گروه. کاربر باید تعداد گروه‌ها یا K را تعیین کند و الگوریتم نقاط را بر اساس نزدیکی به مرکز هر گروه تقسیم می‌کند.'),
    ('knn','KNN (K-Nearest Neighbors)','نزدیک‌ترین همسایه‌ها','ml',['classification','embedding','jaccard-similarity'],'نزدیک‌ترین همسایه‌ها؛ الگوریتمی که نمونه‌های مشابه در اطراف ورودی را پیدا و بر اساس آن‌ها تصمیم می‌گیرد. این روش برای تصمیم‌گیری از نمونه‌های نزدیک به داده جدید استفاده می‌کند و به معیار سنجش فاصله وابسته است.'),
    ('knowledge-base','Knowledge Base','پایگاه دانش','rag',['rag','retrieval','vector-database'],'پایگاه دانش؛ مجموعه‌ای از اسناد و اطلاعات سازمان‌یافته که سیستم هوش مصنوعی می‌تواند برای پاسخ‌گویی و بازیابی اطلاعات از آن استفاده کند.'),
    ('kpi','KPI (Key Performance Indicator)','شاخص کلیدی عملکرد','software',['evaluation-metric','business-intelligence','ai-strategy'],'شاخص کلیدی عملکرد؛ معیارهای اصلی برای سنجش موفقیت یک سیستم یا مدل. KPI باید قابل اندازه‌گیری و مرتبط با هدف کسب‌وکار باشد؛ مثلاً کاهش زمان پاسخ‌گویی یا افزایش نرخ تبدیل.'),
    ('label','Label','برچسب','ml',['data-labeling','supervised-learning','classification'],'برچسب؛ پاسخ یا دسته صحیح برای یک نمونه در مسائل طبقه‌بندی. در یک دیتاست تشخیص تصویر، مثلاً «گربه» یا «سگ» می‌تواند Label نمونه باشد.'),
    ('language-model','Language Model','مدل زبانی','llm',['llm','token','transformer'],'مدل زبانی؛ مدلی که احتمال توالی کلمات را یاد می‌گیرد و می‌تواند متن تولید کند. مدل زبانی می‌تواند برای پیش‌بینی، تکمیل یا تولید متن و در مدل‌های پیشرفته‌تر برای استدلال و انجام وظایف زبانی استفاده شود.'),
    ('lmm','Large Multimodal Model (LMM)','مدل چندوجهی بزرگ','llm',['vlm','multimodal-ai','llm'],'مدل چندوجهی بزرگ؛ مدل بزرگی که برای کار هم‌زمان با چند نوع داده مانند متن، تصویر، صدا یا ویدیو طراحی شده است.'),
    ('latency','Latency','تأخیر','deployment',['throughput','inference','deployment'],'تأخیر؛ مدت زمانی که از ارسال درخواست تا دریافت پاسخ یا نتیجه سپری می‌شود.'),
    ('layer','Layer','لایه','dl',['hidden-layer','neural-network'],'لایه؛ بخش‌های متوالی در شبکه عصبی که داده از آن‌ها عبور می‌کند. هر لایه می‌تواند نوع خاصی از تبدیل را روی داده انجام دهد و مجموعه لایه‌ها معماری شبکه را می‌سازد.'),
    ('learning-rate','Learning Rate','نرخ یادگیری','training',['optimizer','hyperparameter','convergence'],'نرخ یادگیری؛ عددی که تعیین می‌کند مدل در هر مرحله چقدر وزن‌ها را تغییر دهد. اگر نرخ یادگیری خیلی بزرگ باشد آموزش ممکن است ناپایدار شود و اگر خیلی کوچک باشد یادگیری بسیار کند خواهد شد.'),
    ('llm-evaluation','LLM Evaluation','ارزیابی مدل زبانی بزرگ','evaluation',['llm','benchmark','ai-evaluation'],'ارزیابی مدل زبانی بزرگ؛ بررسی کیفیت یک LLM در کارهایی مانند پاسخ‌گویی، استدلال، پیروی از دستور، دقت و تولید متن.'),
    ('llm','LLM (Large Language Model)','مدل زبانی بزرگ','llm',['language-model','transformer','foundation-model'],'مدل زبانی بزرگ؛ مدل هوش مصنوعی آموزش‌دیده روی متن بسیار زیاد برای درک و تولید زبان انسان. LLMها پایه بسیاری از چت‌بات‌ها، دستیارهای هوشمند، ابزارهای تولید محتوا و سیستم‌های پردازش متن امروزی هستند.'),
    ('long-context','Long Context','زمینه طولانی','llm',['context-window','llm','token'],'زمینه طولانی؛ توانایی مدل برای پردازش حجم زیادی از متن یا اطلاعات در یک درخواست یا مکالمه.'),
    ('long-term-memory','Long-Term Memory','حافظه بلندمدت','agents',['memory','short-term-memory','agent-memory'],'حافظه بلندمدت؛ اطلاعاتی که برای استفاده در تعاملات یا وظایف آینده به شکل پایدارتر ذخیره می‌شود.'),
    ('lora','LoRA (Low-Rank Adaptation)','سازگاری با رتبه پایین','training',['adapter','fine-tuning','peft'],'سازگاری با رتبه پایین؛ روش سبک برای تنظیم دقیق مدل‌های بزرگ با اضافه کردن تعداد کمی پارامتر. LoRA به‌خصوص برای تخصصی‌سازی مدل‌های بزرگ با هزینه محاسباتی و حافظه کمتر از Fine-tuning کامل محبوب است.'),
    ('lstm','LSTM (Long Short-Term Memory)','حافظه کوتاه‌مدت بلند','dl',['rnn','neural-network','transformer'],'حافظه کوتاه‌مدت بلند؛ نوعی شبکه عصبی بازگشتی برای کار با داده‌های دنباله‌ای مثل متن و زمان. LSTM با سازوکار حافظه‌ای خود می‌تواند برخی وابستگی‌های بلندمدت در داده‌های ترتیبی را بهتر مدیریت کند.'),
    ('machine-learning','Machine Learning','یادگیری ماشین','ml',['supervised-learning','deep-learning','training-data'],'یادگیری ماشین؛ شاخه‌ای از هوش مصنوعی که در آن مدل‌ها از داده‌ها یاد می‌گیرند بدون برنامه‌نویسی صریح تمام قواعد. در یادگیری ماشین، به جای نوشتن همه قوانین به‌صورت دستی، مدل از نمونه‌های داده الگوهای لازم را یاد می‌گیرد.'),
    ('mcp','MCP (Model Context Protocol)','پروتکل متن مدل','agents',['tool-use','tool-calling','knowledge-base'],'پروتکل متن مدل؛ استانداردی برای اتصال مدل‌های هوش مصنوعی به ابزارها و پایگاه‌های داده خارجی. MCP برای استانداردتر کردن نحوه دسترسی مدل‌ها به ابزارها و منابع خارجی طراحی شده و می‌تواند ساخت اتصال‌ها را ساده‌تر کند.'),
    ('memory','Memory','حافظه','agents',['long-term-memory','short-term-memory','agent-memory'],'حافظه؛ اطلاعاتی که یک سیستم AI برای حفظ زمینه، ترجیحات یا نتایج قبلی در اختیار دارد.'),
    ('ml','ML (Machine Learning)','یادگیری ماشین (ML)','ml',['machine-learning'],'یادگیری ماشین؛ مخفف Machine Learning. ML شکل کوتاه‌شده اصطلاح Machine Learning است و همان مفهوم یادگیری ماشین را بیان می‌کند.'),
    ('mlops','MLOps (Machine Learning Operations)','عملیات یادگیری ماشین','deployment',['deployment','model-drift','monitoring'],'عملیات یادگیری ماشین؛ روش‌ها و ابزارها برای استقرار، پایش و نگهداری مدل‌ها در محیط واقعی. MLOps همکاری بین توسعه، داده و عملیات را برای تبدیل مدل آزمایشی به یک سرویس پایدار ساده‌تر می‌کند.'),
    ('model','Model','مدل','fundamentals',['parameter','training-data','inference'],'مدل؛ نتیجه آموزش که می‌تواند پیش‌بینی، طبقه‌بندی یا تولید محتوا انجام دهد. مدل را می‌توان موتور تصمیم‌گیری یا تولید در یک سیستم AI دانست که پس از آموزش روی داده‌های جدید اجرا می‌شود.'),
    ('model-api','Model API','API مدل','deployment',['api','inference-api','model'],'API مدل؛ رابطی که به برنامه‌ها اجازه می‌دهد قابلیت‌های یک مدل هوش مصنوعی را از طریق درخواست‌های نرم‌افزاری استفاده کنند.'),
    ('model-drift','Model Drift','رانش مدل','deployment',['concept-drift','monitoring','mlops'],'رانش مدل؛ کاهش تدریجی دقت مدل به دلیل تغییر الگوهای داده در طول زمان. پایش مداوم عملکرد کمک می‌کند افت تدریجی کیفیت مدل زودتر شناسایی شود.'),
    ('model-routing','Model Routing','مسیریابی مدل','deployment',['cascade-model','latency','token-cost'],'مسیریابی مدل؛ انتخاب خودکار مدل مناسب برای هر درخواست بر اساس عواملی مانند نوع کار، کیفیت موردنیاز، سرعت یا هزینه.'),
    ('moe','MoE (Mixture of Experts)','مخلوط خبرگان','dl',['transformer','parameter','inference'],'مخلوط خبرگان؛ معماری‌ای که چند زیرمدل تخصصی را ترکیب می‌کند تا بهره‌وری و کیفیت بهتر شود. در MoE معمولاً برای هر ورودی فقط بخشی از Expertها فعال می‌شوند و همین موضوع می‌تواند استفاده از مدل بزرگ را کارآمدتر کند.'),
    ('multi-agent-system','Multi-Agent System','سیستم چندعاملی','agents',['agent','agentic-workflow','delegation'],'سیستم چندعاملی؛ سیستمی متشکل از چند عامل هوشمند که می‌توانند وظایف را بین خود تقسیم کرده و با یکدیگر همکاری کنند.'),
    ('multi-modal','Multi-Modal','چند‌حالته','generative',['multimodal-ai','vlm','lmm'],'چند‌حالته؛ مدلی که چند نوع ورودی مثل متن، تصویر و صدا را هم‌زمان پردازش می‌کند. مثلاً یک مدل چندحالته می‌تواند سؤال متنی را همراه با یک تصویر دریافت کند و بر اساس هر دو پاسخ دهد.'),
    ('multimodal-ai','Multimodal AI','هوش مصنوعی چندوجهی','generative',['multi-modal','vlm','lmm'],'هوش مصنوعی چندوجهی؛ سیستمی که می‌تواند چند نوع اطلاعات مانند متن، تصویر، صدا و ویدیو را دریافت یا تولید کند و ارتباط میان آن‌ها را درک کند.'),
    ('neural-network','Neural Network','شبکه عصبی','dl',['deep-learning','layer','weight'],'شبکه عصبی؛ مدل الهام‌گرفته از مغز انسان با نورون‌ها و ارتباطات بین آن‌ها. شبکه عصبی با یادگیری وزن ارتباط‌ها می‌تواند الگوهای پیچیده‌ای را از داده استخراج کند.'),
    ('nlg','NLG (Natural Language Generation)','تولید زبان طبیعی','llm',['nlp','llm','language-model'],'تولید زبان طبیعی؛ تولید متن قابل فهم برای انسان توسط ماشین. NLG به سیستم اجازه می‌دهد اطلاعات یا تصمیم‌های داخلی را به متن طبیعی و قابل فهم تبدیل کند.'),
    ('nlp','NLP (Natural Language Processing)','پردازش زبان طبیعی','application',['nlu','nlg','sentiment-analysis'],'پردازش زبان طبیعی؛ شاخه‌ای از هوش مصنوعی که با متن و گفتار انسان سروکار دارد. NLP پایه بسیاری از قابلیت‌ها مانند ترجمه، خلاصه‌سازی، جست‌وجوی معنایی، تحلیل احساسات و چت‌بات‌هاست.'),
    ('nlu','NLU (Natural Language Understanding)','درک زبان طبیعی','application',['nlp','question-answering'],'درک زبان طبیعی؛ فهمیدن معنای متن و گفتار توسط هوش مصنوعی. NLU تلاش می‌کند منظور، موجودیت‌ها، موضوع و ارتباط‌های موجود در زبان انسان را استخراج کند.'),
    ('node','Node','گره','math',['gnn','neural-network'],'گره؛ واحد بنیادی در گراف یا شبکه عصبی که ورودی را پردازش می‌کند. در یک گراف، Node می‌تواند نماینده یک فرد، محصول یا شهر باشد و در یک شبکه عصبی نیز به واحدهای پردازشی اشاره کند.'),
    ('normalization','Normalization','نرمال‌سازی','ml',['batch-normalization','feature-engineering','training-data'],'نرمال‌سازی؛ مقیاس‌کردن داده‌ها به دامنه‌ای ثابت برای کمک به آموزش بهتر. نرمال‌سازی می‌تواند اختلاف مقیاس بین ویژگی‌ها را کاهش دهد و در برخی مدل‌ها آموزش را پایدارتر کند.'),
    ('open-source-model','Open-Source Model','مدل متن‌باز','software',['foundation-model','llm','deployment'],'مدل متن‌باز؛ مدلی که کد، وزن‌ها یا بخش‌هایی از اجزای آن با شرایط مشخصی در دسترس دیگران قرار گرفته و امکان استفاده یا تغییر آن وجود دارد.'),
    ('optimization','Optimization','بهینه‌سازی','math',['optimizer','cost-function','convergence'],'بهینه‌سازی؛ فرآیند تنظیم پارامترهای مدل برای کاهش خطا. هدف بهینه‌سازی معمولاً پیدا کردن پارامترهایی است که معیار خطا یا هزینه را تا حد ممکن کاهش دهند.'),
    ('optimizer','Optimizer','بهینه‌ساز','training',['optimization','learning-rate','parameter'],'بهینه‌ساز؛ الگوریتمی مثل Adam یا SGD که وزن‌ها را در طول آموزش تغییر می‌دهد. Optimizer با استفاده از گرادیان یا روش‌های دیگر تعیین می‌کند پارامترهای مدل در هر مرحله چگونه به‌روزرسانی شوند.'),
    ('overfitting','Overfitting','بیش‌برازش','ml',['regularization','underfitting','cross-validation'],'بیش‌برازش؛ زمانی که مدل روی جزئیات داده آموزشی بیش‌ازحد تمرکز می‌کند و روی داده جدید ضعیف می‌شود. برای کاهش بیش‌برازش می‌توان از روش‌هایی مانند Regularization، افزایش داده یا توقف زودهنگام استفاده کرد.'),
    ('parameter','Parameter','پارامتر','training',['weight','hyperparameter','capacity'],'پارامتر؛ متغیرهای داخلی مدل مثل وزن‌ها که در طول آموزش یاد گرفته می‌شوند. پارامترها در فرآیند آموزش از داده یاد گرفته می‌شوند و تعداد زیاد آن‌ها معمولاً به ظرفیت بیشتر مدل مربوط است.'),
    ('pattern-recognition','Pattern Recognition','تشخیص الگو','ml',['classification','computer-vision'],'تشخیص الگو؛ شناسایی نظم‌ها و ساختارهای تکراری در داده مثل تشخیص چهره. تشخیص الگو در حوزه‌هایی مانند تشخیص چهره، تشخیص دست‌خط، تحلیل صدا و کشف تقلب استفاده می‌شود.'),
    ('perceptron','Perceptron','پرسپترون','dl',['neural-network','classification'],'پرسپترون؛ ساده‌ترین نوع شبکه عصبی با یک لایه. پرسپترون می‌تواند یک تصمیم دودویی ساده بگیرد و یکی از پایه‌های تاریخی شبکه‌های عصبی مدرن محسوب می‌شود.'),
    ('planning','Planning','برنامه‌ریزی','agents',['agent','agentic-workflow','subtask'],'برنامه‌ریزی؛ مشخص کردن مراحل و اقدامات لازم برای رسیدن یک سیستم هوشمند به هدف.'),
    ('post-training','Post-training','پس‌آموزش','training',['pretraining','sft','rlhf'],'پس‌آموزش؛ مجموعه روش‌هایی که بعد از آموزش اولیه برای بهتر کردن رفتار، توانایی یا هماهنگی مدل انجام می‌شوند.'),
    ('precision','Precision','دقت','evaluation',['recall','confusion-matrix','false-positive'],'دقت؛ نسبت پیش‌بینی‌های مثبت درست به تمام پیش‌بینی‌های مثبت. Precision زمانی مهم است که مثبت کاذب هزینه زیادی داشته باشد؛ مثلاً وقتی نمی‌خواهیم موارد سالم را اشتباه علامت‌گذاری کنیم.'),
    ('predictive-analytics','Predictive Analytics','تحلیل پیش‌بینی‌کننده','software',['machine-learning','business-intelligence'],'تحلیل پیش‌بینی‌کننده؛ استفاده از داده و مدل‌ها برای پیش‌بینی آینده مثل فروش یا رفتار مشتری. کسب‌وکارها می‌توانند از آن برای پیش‌بینی فروش، تقاضا، ریسک، ریزش مشتری یا خرابی تجهیزات استفاده کنند.'),
    ('pretrained-model','Pretrained Model','مدل از پیش‌آموزش‌دیده','training',['pretraining','foundation-model','fine-tuning'],'مدل از پیش‌آموزش‌دیده؛ مدلی که قبلاً روی حجم بزرگی از داده آموزش دیده و می‌توان آن را مستقیماً استفاده یا برای کار دیگری تنظیم کرد.'),
    ('pretraining','Pretraining','پیش‌آموزش','training',['training-data','pretrained-model','post-training'],'پیش‌آموزش؛ مرحله‌ای که مدل ابتدا روی حجم بزرگی از داده برای یادگیری الگوهای عمومی آموزش می‌بیند.'),
    ('prompt','Prompt','دستور','prompt',['prompt-engineering','system-prompt','context'],'دستور؛ متن یا ورودی‌ای که به مدل داده می‌شود تا پاسخ یا خروجی تولید کند. یک Prompt خوب معمولاً هدف، زمینه، محدودیت‌ها و شکل خروجی مورد انتظار را تا حد کافی مشخص می‌کند.'),
    ('prompt-engineering','Prompt Engineering','مهندسی دستور','prompt',['prompt','prompt-template','few-shot-prompting'],'مهندسی دستور؛ هنر طراحی دستورهای مؤثر برای گرفتن بهترین پاسخ از مدل. با طراحی بهتر Prompt می‌توان پاسخ‌های دقیق‌تر، ساختاریافته‌تر و متناسب‌تر با هدف گرفت، بدون اینکه الزاماً مدل را دوباره آموزش داد.'),
    ('prompt-injection','Prompt Injection','تزریق دستور','security',['jailbreak','ai-security','system-prompt'],'تزریق دستور؛ حمله یا ورودی مخربی که تلاش می‌کند دستورهای اصلی یک سیستم AI را دور بزند یا مدل را وادار به انجام کاری ناخواسته کند.'),
    ('prompt-template','Prompt Template','قالب دستور','prompt',['prompt','prompt-engineering'],'قالب دستور؛ الگوی از پیش طراحی‌شده‌ای برای ساخت Promptهای مشابه که بخش‌هایی از آن می‌تواند با اطلاعات جدید پر شود.'),
    ('pruning','Pruning','هرس مدل','training',['quantization','model','inference'],'هرس مدل؛ حذف بخش‌هایی از پارامترها یا اتصالات مدل که اهمیت کمتری دارند برای کاهش حجم و هزینه محاسبات.'),
    ('q-learning','Q-Learning','کیو-لرنینگ','reinforcement',['q-value','q-network','reinforcement-learning'],'کیو-لرنینگ؛ الگوریتم یادگیری تقویتی برای یادگیری بهترین اقدام در هر وضعیت. عامل به‌تدریج یاد می‌گیرد برای هر وضعیت و اقدام چه مقدار پاداش آینده انتظار داشته باشد و بر اساس آن تصمیم بگیرد.'),
    ('qlora','QLoRA','کیولورا','training',['lora','quantization','fine-tuning'],'کیولورا؛ روشی برای تنظیم دقیق مدل‌های بزرگ که از Quantization و LoRA برای کاهش مصرف حافظه استفاده می‌کند.'),
    ('q-network','Q-Network','شبکه کیو','reinforcement',['q-learning','reinforcement-learning'],'شبکه کیو؛ شبکه عصبی که در Q-Learning برای تخمین مقدار Q استفاده می‌شود. Q-Network یک شبکه عصبی است که مقدار Q را برای حالت‌ها یا اقدامات مختلف تخمین می‌زند.'),
    ('quadratic-loss','Quadratic Loss','زیان درجه دو','math',['cost-function','loss-function'],'زیان درجه دو؛ تابع خطایی که مجذور تفاوت پیش‌بینی و واقعیت را محاسبه می‌کند. این تابع خطا به اختلاف‌های بزرگ‌تر وزن بیشتری می‌دهد، چون اختلاف به توان دو می‌رسد.'),
    ('quality-score','Quality Score','امتیاز کیفیت','evaluation',['evaluation-metric','llm-evaluation'],'امتیاز کیفیت؛ معیاری برای سنجش کیفیت خروجی مدل یا داده. این امتیاز باید بر اساس معیار مشخص تعریف شود تا بتوان کیفیت خروجی‌ها یا داده‌ها را به‌صورت قابل مقایسه سنجید.'),
    ('quantile-regression','Quantile Regression','رگرسیون چارکی','math',['regression','quadratic-loss'],'رگرسیون چارکی؛ نوعی رگرسیون که به جای میانگین، چارک‌های توزیع را پیش‌بینی می‌کند. این روش به جای پیش‌بینی یک مقدار میانگین، می‌تواند مثلاً حد پایین یا بالای بازه مورد انتظار را تخمین بزند.'),
    ('quantization','Quantization','کوانتیزه‌کردن','training',['quantized-model','pruning','inference'],'کوانتیزه‌کردن؛ کاهش دقت اعداد در مدل برای کوچک‌تر و سریع‌تر شدن آن. کوانتیزه‌سازی می‌تواند حجم مدل و مصرف حافظه را کاهش دهد و اجرای آن را روی سخت‌افزار محدود آسان‌تر کند، هرچند ممکن است کمی از دقت کم شود.'),
    ('quantized-model','Quantized Model','مدل کوانتیزه‌شده','deployment',['quantization','edge-ai','slm'],'مدل کوانتیزه‌شده؛ مدلی که دقت عددی پارامترهای آن کاهش داده شده تا حجم و مصرف حافظه کمتر و اجرای آن سریع‌تر شود.'),
    ('quantum-machine-learning','Quantum Machine Learning','یادگیری ماشین کوانتومی','hardware',['machine-learning'],'یادگیری ماشین کوانتومی؛ استفاده از اصول فیزیک کوانتوم برای الگوریتم‌های یادگیری. این حوزه هنوز در حال توسعه است و هدف آن بررسی مزیت‌های احتمالی رایانش کوانتومی برای برخی مسائل یادگیری ماشین است.'),
    ('query','Query','پرس‌وجو','rag',['retrieval','rag','semantic-search'],'پرس‌وجو؛ درخواستی که کاربر یا سیستم برای دریافت اطلاعات از مدل یا پایگاه دانش ارسال می‌کند. در یک سیستم RAG، Query همان سؤال یا درخواست کاربر است که برای پیدا کردن اطلاعات مرتبط استفاده می‌شود.'),
    ('question-answering','Question Answering','پاسخ به پرسش','application',['nlu','rag','knowledge-base'],'پاسخ به پرسش؛ توانایی مدل برای پاسخ دادن به سوالات بر اساس متن یا دانش. سیستم‌های پاسخ به پرسش می‌توانند پاسخ را از متن داده‌شده، پایگاه دانش یا منابع بازیابی‌شده استخراج یا تولید کنند.'),
    ('q-value','Q-Value','مقدار کیو','reinforcement',['q-learning','value-function'],'مقدار کیو؛ امتیاز پیش‌بینی‌شده برای یک اقدام در یک وضعیت خاص در یادگیری تقویتی. هرچه Q-Value یک اقدام بیشتر باشد، از دید مدل آن اقدام در آن وضعیت مطلوب‌تر است.'),
    ('rag','RAG (Retrieval-Augmented Generation)','تولید تقویت‌شده با بازیابی (RAG)','rag',['retrieval','retriever','vector-database'],'تولید تقویت‌شده با بازیابی؛ ترکیب جست‌وجو در منابع واقعی با تولید متن توسط مدل. RAG ابتدا اطلاعات مرتبط را از منابعی مانند اسناد یا پایگاه دانش پیدا می‌کند و سپس مدل با تکیه بر آن‌ها پاسخ می‌سازد؛ این روش برای چت‌بات‌های سازمانی بسیار کاربردی است.'),
    ('reasoning-model','Reasoning Model','مدل استدلالی','llm',['chain-of-thought','inference-time-compute','planning'],'مدل استدلالی؛ مدلی که برای حل مسائل چندمرحله‌ای و پیچیده، توانایی بیشتری در برنامه‌ریزی و استدلال دارد.'),
    ('recall','Recall','فراخوانی','evaluation',['precision','confusion-matrix','false-negative'],'فراخوانی؛ نسبت موارد مثبت درست شناسایی‌شده به همه موارد مثبت واقعی. Recall زمانی مهم است که از دست دادن یک مورد مثبت هزینه بالایی داشته باشد؛ مثلاً در برخی کاربردهای تشخیص بیماری یا کشف تقلب.'),
    ('regularization','Regularization','قاعده‌گذاری','ml',['overfitting','bias-variance-tradeoff','hyperparameter'],'قاعده‌گذاری؛ تکنیک‌هایی برای جلوگیری از بیش‌برازش در مدل‌ها. این روش‌ها مدل را از یادگیری بیش‌ازحد جزئیات داده آموزشی بازمی‌دارند تا روی داده‌های جدید بهتر عمل کند.'),
    ('reinforcement-learning','Reinforcement Learning','یادگیری تقویتی','reinforcement',['q-learning','reward-model','value-function'],'یادگیری تقویتی؛ نوعی یادگیری که در آن یک عامل با پاداش و تنبیه از محیط یاد می‌گیرد. عامل با آزمون و خطا یاد می‌گیرد کدام اقدامات در بلندمدت پاداش بیشتری ایجاد می‌کنند.'),
    ('reranking','Reranking','بازرتبه‌بندی','rag',['retrieval','candidate-generation','hybrid-search'],'بازرتبه‌بندی؛ مرتب‌سازی دوباره نتایج بازیابی‌شده با یک روش دقیق‌تر برای انتخاب مرتبط‌ترین موارد.'),
    ('retrieval','Retrieval','بازیابی','rag',['retriever','rag','vector-search'],'بازیابی؛ مرحله پیدا کردن اطلاعات مرتبط از میان اسناد، پایگاه داده یا منابع دیگر برای استفاده در پاسخ یا تصمیم‌گیری.'),
    ('retriever','Retriever','بازیاب','rag',['retrieval','rag','embedding'],'بازیاب؛ بخشی از سیستم RAG که مسئول پیدا کردن قطعات مرتبط از میان منابع موجود است.'),
    ('rl','RL (Reinforcement Learning)','یادگیری تقویتی (RL)','reinforcement',['reinforcement-learning'],'یادگیری تقویتی؛ مخفف Reinforcement Learning. RL شکل کوتاه‌شده Reinforcement Learning و همان یادگیری تقویتی است.'),
    ('rlhf','RLHF (Reinforcement Learning from Human Feedback)','یادگیری تقویتی از بازخورد انسانی','alignment',['reward-model','alignment','dpo'],'یادگیری تقویتی از بازخورد انسانی؛ تنظیم مدل‌ها بر اساس ترجیحات و بازخورد انسان‌ها. این روش به مدل کمک می‌کند خروجی‌هایی تولید کند که بیشتر با ترجیحات و انتظارات انسان هماهنگ باشند.'),
    ('rnn','RNN (Recurrent Neural Network)','شبکه عصبی بازگشتی','dl',['lstm','neural-network','attention-mechanism'],'شبکه عصبی بازگشتی؛ نوعی شبکه عصبی برای پردازش دنباله‌ها مثل متن یا داده زمانی. RNN برای داده‌های ترتیبی طراحی شده و در گذشته در پردازش متن و سری‌های زمانی کاربرد زیادی داشته است.'),
    ('robotics','Robotics','رباتیک','application',['reinforcement-learning','computer-vision','planning'],'رباتیک؛ زمینه‌ای که به طراحی، ساخت و کنترل ربات‌های هوشمند می‌پردازد. ترکیب رباتیک با AI می‌تواند به ربات‌ها توانایی دیدن محیط، تصمیم‌گیری، برنامه‌ریزی و تعامل هوشمندتر بدهد.'),
    ('self-attention','Self-Attention','توجه به خود','dl',['attention-mechanism','transformer'],'توجه به خود؛ سازوکاری که به مدل اجازه می‌دهد ارتباط و اهمیت بخش‌های مختلف یک ورودی را نسبت به یکدیگر بررسی کند.'),
